"""Copy dashboard/index.html into the firmware as a C string (run after editing the dashboard)."""
from pathlib import Path

root = Path(__file__).resolve().parent.parent
html = (root / "dashboard" / "index.html").read_text(encoding="utf-8")
assert ')rawliteral"' not in html
out = root / "firmware" / "ResQCam_Gateway" / "dashboard_html.h"
out.write_text(
    "// GENERATED by tools/embed_dashboard.py from dashboard/index.html - edit that file instead.\n"
    "#pragma once\n#include <pgmspace.h>\n\n"
    f'static const char DASHBOARD_HTML[] PROGMEM = R"rawliteral({html})rawliteral";\n',
    encoding="utf-8")
print(f"{out.relative_to(root)}: {len(html.encode())} bytes")
